      ... on GmailAccount {
        authenticated
        email
        id
        primary
        insufficientScopeDetected
        reauthRecommended
        connectedAt
        disconnectedAt
      }
      ... on OutlookAccount {
        authenticated
        email
        id
        primary
        connectedAt
        disconnectedAt
      }
    }
  }
  establishedClientConnections(
    clientTypes: [UNSPECIFIED, MINIS_MINI, PARTNER]
  ) {
    createdAt
    id
    handle
    disconnectUrl
    disconnectedAt
    direction
    scope
    status
    scopes {
      ... on Scope {
        title
        description
        scope
      }
